mapper.select:
SELECT MAX(sort_order) FROM sys_dict_type WHERE deleted = 0
AND tenant_id IS NULL
AND tenant_id = #{tenantId}

SELECT id, dict_type_id, item_value, source, source_ref, label_key, label_labels, tone, selectable, status, sort_order, created_at, updated_at, version, deleted FROM sys_dict_item WHERE dict_type_id IN
#{typeId}
ORDER BY dict_type_id, sort_order, id

mapper.insert:
INSERT INTO sys_dict_type (
    id, tenant_id, code, kind, source, name_key, name_labels, status, sort_order, source_ref, deleted
) VALUES (
    #{type.id}, #{type.tenantId}, #{type.code}, #{type.kind}, 'CONFIGURATION', NULL,
    CAST(#{type.nameLabels} AS JSONB), #{type.status}, #{type.sortOrder}, NULL, 0
)

mapper.update:
UPDATE sys_dict_type SET name_labels = CAST(#{nameLabels} AS JSONB), status = #{status}, updated_at = CURRENT_TIMESTAMP, version = version + 1 WHERE id = #{dictionaryId} AND kind IN ('BUSINESS_CODE', 'INPUT_SUGGESTION') AND version = #{version} AND deleted = 0
AND tenant_id IS NULL
AND tenant_id = #{tenantId}

UPDATE sys_dict_item item SET item_value = #{value}, label_labels = CAST(#{labelLabels} AS JSONB), tone = #{tone}, selectable = #{selectable}, status = #{status}, updated_at = CURRENT_TIMESTAMP, version = item.version + 1 WHERE item.id = #{itemId} AND item.dict_type_id = #{dictionaryId} AND item.version = #{version} AND item.deleted = 0 AND EXISTS ( SELECT 1 FROM sys_dict_type type WHERE type.id = item.dict_type_id AND type.kind = #{kind} AND type.deleted = 0
AND type.tenant_id IS NULL
AND type.tenant_id = #{tenantId}
)

UPDATE sys_dict_type
SET status = 'DISABLED',
    deleted = 1,
    updated_at = CURRENT_TIMESTAMP,
    version = version + 1
WHERE id = #{dictionaryId}
  AND kind = #{kind}
  AND kind IN ('BUSINESS_CODE', 'INPUT_SUGGESTION')
  AND source = 'CONFIGURATION'
  AND version = #{version}
  AND deleted = 0


        AND tenant_id IS NULL


        AND tenant_id = #{tenantId}

UPDATE sys_dict_item item SET status = 'DISABLED', selectable = FALSE, deleted = 1, updated_at = CURRENT_TIMESTAMP, version = item.version + 1 WHERE item.id = #{itemId} AND item.dict_type_id = #{dictionaryId} AND item.version = #{version} AND item.source = 'CONFIGURATION' AND item.deleted = 0 AND EXISTS ( SELECT 1 FROM sys_dict_type type WHERE type.id = item.dict_type_id AND type.kind = 'BUSINESS_CODE' AND type.deleted = 0
AND type.tenant_id IS NULL
AND type.tenant_id = #{tenantId}
)

mapper.delete:
DELETE FROM sys_dict_item item
WHERE item.id = #{itemId}
  AND item.dict_type_id = #{dictionaryId}
  AND item.version = #{version}
  AND item.deleted = 0
  AND EXISTS (
      SELECT 1
      FROM sys_dict_type type
      WHERE type.id = item.dict_type_id
        AND type.kind = 'INPUT_SUGGESTION'
        AND type.deleted = 0


                AND type.tenant_id IS NULL


                AND type.tenant_id = #{tenantId}


  )

WITH type_ids AS MATERIALIZED (
    SELECT id
    FROM sys_dict_type
    WHERE tenant_id = #{tenantId}
      AND deleted = 1
), deleted_items AS (
    DELETE FROM sys_dict_item WHERE dict_type_id IN (SELECT id FROM type_ids)
)
DELETE FROM sys_dict_type WHERE id IN (SELECT id FROM type_ids)

mapper.update:
UPDATE sys_dict_type AS type SET sort_order = ordering.sort_order, updated_at = CURRENT_TIMESTAMP, version = type.version + 1 FROM (VALUES
(#{order.id}, #{order.sortOrder}, #{order.version})
) AS ordering(type_id, sort_order, expected_version) WHERE type.id = ordering.type_id AND type.version = ordering.expected_version AND type.deleted = 0
AND type.tenant_id IS NULL
AND type.tenant_id = #{tenantId}

UPDATE sys_dict_item item SET sort_order = ordering.sort_order, updated_at = CURRENT_TIMESTAMP, version = item.version + 1 FROM (VALUES
(#{order.id}, #{order.sortOrder}, #{order.version})
) AS ordering(item_id, sort_order, expected_version) WHERE item.id = ordering.item_id AND item.dict_type_id = #{dictionaryId} AND item.version = ordering.expected_version AND item.deleted = 0 AND EXISTS ( SELECT 1 FROM sys_dict_type type WHERE type.id = item.dict_type_id AND type.deleted = 0
AND type.tenant_id IS NULL
AND type.tenant_id = #{tenantId}
)
